from pathlib import Path
p=Path(__file__).resolve().parents[1]/'多次执行核销.html'
s=p.read_text(encoding='utf-8')
css='''body.execution-with-sidebar{display:grid;grid-template-columns:248px minmax(0,1fr);align-items:start;gap:20px;padding:16px}body.execution-with-sidebar>main{padding:0;width:100%;min-width:0;max-width:none}#execution-application-sidebar{background:#fff;border:1px solid #dce3ec;box-shadow:0 2px 8px #0000000a;padding:20px;min-height:calc(100vh - 32px);font-size:13px;overflow-wrap:anywhere}#execution-application-sidebar h2{font-size:15px;margin-bottom:20px}#execution-application-sidebar dl{margin:0}#execution-application-sidebar dt{color:#263445;margin-top:20px}#execution-application-sidebar dd{margin:4px 0 0;color:#586779}#execution-application-sidebar .money{color:#176bc5;font-weight:600}@media(max-width:800px){body.execution-with-sidebar{grid-template-columns:1fr;padding:12px}#execution-application-sidebar{min-height:0}#execution-application-sidebar dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#execution-application-sidebar dl div{min-width:0}#execution-application-sidebar dt{margin:0}}'''
s=s.replace('</style>',css+'</style>',1)
anchor='function render(){const app=db.application;'
assert anchor in s
function='''function renderSidebar(){if(isWriteoff)return;document.body.classList.add('execution-with-sidebar');let panel=document.getElementById('execution-application-sidebar');if(!panel){panel=document.createElement('aside');panel.id='execution-application-sidebar';panel.setAttribute('aria-label','关联活动申请摘要');document.body.prepend(panel)}panel.replaceChildren();const heading=document.createElement('h2');heading.textContent='关联申请信息';panel.append(heading);const app=db.application;if(!app){const p=document.createElement('p');p.textContent='确认申请快照后，展示对应申请信息。';panel.append(p);return}const temp=document.createElement('div');temp.innerHTML=app.html;const entries=[['单据编号',app.id]];temp.querySelectorAll('.basic-field').forEach(field=>{const label=field.querySelector('span')?.textContent.replaceAll('*','').replace(/[：:]$/,'').trim();const controls=Array.from(field.querySelectorAll('input,select,textarea'));const value=controls.length?controls.filter(el=>!['radio','checkbox'].includes(el.type)||el.checked).map(el=>el.value).join(' 至 '):(field.querySelector('b')?.textContent||field.lastElementChild?.textContent||'').trim();if(label&&!label.includes('预算费用')&&!label.includes('预计我司承担'))entries.push([label,value])});const budget=sum(app.items.map(i=>i.budget));entries.push(['预算费用合计（元）',money(budget)],['我司承担费用（元）',money(round(budget*app.share/100))],['支付方式',app.pay]);const dl=document.createElement('dl');entries.forEach(([label,value])=>{const wrap=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label+'：';dd.textContent=value||'—';if(label.includes('费用'))dd.className='money';wrap.append(dt,dd);dl.append(wrap)});panel.append(dl)}
'''
s=s.replace(anchor,function+'function render(){const app=db.application;renderSidebar();')
p.write_text(s,encoding='utf-8')
